#!/usr/bin/env node

function usage(msg)
{
  if (msg) {
    console.log(msg,'\n\n');
  }
  console.log('Usage: ' + process.argv[1] + ' [-v] <package.json>');
  console.log();
  console.log('Recursively outputs the names of all the packages required');
  console.log('by the provided package.json following file: URLs only.');
  console.log('Immediate dev dependencies are also output.');
  console.log();
  console.log('-v\tOutput the desired package version too');
  console.log();
  process.exit(1);
}

var fileName;
var outputVersion = false;

switch (process.argv.length) {
case 3:
  fileName = process.argv[2];
  break;
case 4:
  if (process.argv[2] !== '-v') {
    usage('Unknown command line argument: ' + process.argv[2]);
  }
  outputVersion = true;
  fileName = process.argv[3];
  break;
default:
  usage('Invalid command-line arguments');
}


PackageDeps(fileName, outputVersion, 1);
process.exit(0);

function PackageDeps(packageFile, outputVersion, depth)
{
  var fs = require('fs');
  var package = JSON.parse(fs.readFileSync(packageFile, 'utf8'));
  function outputDeps(dependencies) {
    if (!dependencies) return;

    packageNames = Object.keys(dependencies);
    packageNames.forEach(function(name) {
      var version = dependencies[name];
      if (version.substr(0, 5) === 'file:') {
        var packageDir = packageFile.substring(0, packageFile.length - 'package.json'.length);
        var subPackageFile = packageDir + version.substring('file:'.length) + '/package.json';
        PackageDeps(subPackageFile, outputVersion, depth + 1)
        return;
      }
      if (outputVersion) {
        console.log(name + '@' + version);
      } else {
        console.log(name);
      }
    });
  }

  outputDeps(package.dependencies);
  if (depth === 1) {
    // devDependencies only for the topmost package.json
    outputDeps(package.devDependencies);
  }
}
